import numpy as np

demo_in = G['Demo pair 1 input']
demo_out = G['Demo pair 1 output']

in_arr = np.array(demo_in)
out_arr = np.array(demo_out)

h,w = in_arr.shape  # 6, 15
H,W = out_arr.shape  # 18, 30

# Hypothesis: output is tiled with 6 copies of input
# Let's verify by checking if output can be divided into 6 regions of size 6×15
print("=== Dividing output into 6 regions of 6x15 ===")
regions = []
for r_block in range(3):  # 3 blocks high
    for c_block in range(2):  # 2 blocks wide
        region = out_arr[r_block*6:(r_block+1)*6, c_block*15:(c_block+1)*15]
        regions.append((r_block, c_block, region))
        print(f"\nRegion ({r_block},{c_block}) shape: {region.shape}")

# Now for each region, check if it matches input with some transformation
def transform_grid(grid, rotation=0):
    """Apply transformations"""
    result = np.copy(grid)
    for _ in range(rotation % 4):
        result = np.rot90(result, k=-1)  # rotate 90° counterclockwise
    return result

def flip_grid(grid, axis='both'):
    """Flip along specified axis"""
    if axis == 'v':
        return np.flipud(grid)
    elif axis == 'h':
        return np.fliplr(grid)
    elif axis == 'both':
        return np.flipud(np.fliplr(grid))
    else:
        return np.fliplr(np.flipud(grid))

# For each region, check all combinations
print("\n=== Checking each region against input with transformations ===")
for rb, cb, region in regions:
    found_match = False

    # Try rotations 0, 90, 180, 270
    for rot in range(4):
        rotated = transform_grid(region, rot)
        if np.array_equal(rotated, in_arr):
            print(f"Region ({rb},{cb}) matches input after {rot} rotations")
            found_match = True

        # Also try with flips combined with rotation
        for flip_axis in ['v', 'h', 'both']:
            flipped = transform_grid(flip_grid(region, flip_axis), rot)
            if np.array_equal(flipped, in_arr):
                print(f"Region ({rb},{cb}) matches input after flip({flip_axis}) + {rot} rotations")
                found_match = True

    if not found_match:
        print(f"Region ({rb},{cb}): NO MATCH FOUND")

        # Show first few values to debug
        print(f"  Region top-left:\n{region[:3,:5]}")
        print(f"  Input top-left:\n{in_arr[:3,:5]}")
